#!/usr/bin/env bash
# scripts/create-identities.sh
#
# README section: "Getting started" step 4
#
# Creates and funds the four test identities needed for local / testnet work.
# Keys are generated by the Stellar CLI and stored in its global keystore —
# they are NEVER printed to stdout, never committed to source control.
#
# Usage:
#   ./scripts/create-identities.sh [--network testnet|local]
#
# Prerequisites:
#   - stellar CLI installed  (cargo install --locked stellar-cli)
#   - For testnet: internet access (Friendbot is called automatically via --fund)
#   - For local: Quickstart container running (see infra/docker/docker-compose.yml)
#
# TODO: verify exact flag names against the version of the Stellar CLI you are
# running.  The flags used here are based on the README and the current
# developers.stellar.org/docs/tools/stellar-cli reference.  Run:
#   stellar keys --help
#   stellar keys generate --help
# to confirm.

set -euo pipefail

NETWORK="${1:-testnet}"

# Accepted values: testnet | local
if [[ "$NETWORK" != "testnet" && "$NETWORK" != "local" ]]; then
  echo "ERROR: --network must be 'testnet' or 'local'" >&2
  exit 1
fi

IDENTITIES=(admin funder school attester)

echo "==> Creating / refreshing identities for network: $NETWORK"

for ID in "${IDENTITIES[@]}"; do
  echo "--> $ID"

  if [[ "$NETWORK" == "testnet" ]]; then
    # --fund calls Friendbot on testnet to credit the new account.
    # TODO: confirm --fund is still the correct flag for your CLI version:
    #   https://developers.stellar.org/docs/tools/stellar-cli
    stellar keys generate \
      --global \
      --network testnet \
      --fund \
      --overwrite \
      "$ID"
  else
    # Local Quickstart network — Friendbot URL differs; the CLI may not
    # support --fund for local.  Create the key and fund via Friendbot manually
    # or with the helper below.
    # TODO: check whether --fund works against your Quickstart container, or
    # whether you need to POST to http://localhost:8000/friendbot?addr=<addr>
    stellar keys generate \
      --global \
      --network local \
      --overwrite \
      "$ID"

    ADDR=$(stellar keys address "$ID")
    echo "    Funding $ID ($ADDR) via Quickstart Friendbot..."
    # TODO: verify the Quickstart Friendbot endpoint for your container version.
    # Reference: https://developers.stellar.org/docs/tools/quickstart
    curl -s "http://localhost:8000/friendbot?addr=${ADDR}" > /dev/null \
      || echo "    WARN: Friendbot call failed — fund manually."
  fi

  # Print only the address (never the secret key).
  ADDR=$(stellar keys address "$ID")
  echo "    Address: $ADDR"
done

echo ""
echo "==> Done.  Addresses above; keys stored in the Stellar CLI global keystore."
echo "    To export an address for use in .env:"
echo "      stellar keys address admin"
echo ""
echo "    NEVER run 'stellar keys show <name>' in CI or commit the output."
